import XCTest
#if canImport(CryptoKit)
import CryptoKit
#else
import Crypto
#endif
@testable import BridgeCore

/// Checks the Swift server side against vectors/vectors.json, generated by reference/gen_vectors.py
/// and shared with the Kotlin tests.
final class VectorTests: XCTestCase {
    private var v: [String: Any] = [:]

    override func setUpWithError() throws {
        // …/bridge/mac/Tests/BridgeCoreTests/VectorTests.swift → …/bridge
        var url = URL(fileURLWithPath: #filePath).resolvingSymlinksInPath()
        for _ in 0..<4 { url.deleteLastPathComponent() }
        url.appendPathComponent("vectors/vectors.json")
        let data = try Data(contentsOf: url)
        v = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
    }

    private func section(_ name: String) throws -> [String: Any] {
        return try XCTUnwrap(v[name] as? [String: Any])
    }

    private func hex(_ s: [String: Any], _ key: String) throws -> Data {
        let str = try XCTUnwrap(s[key] as? String, "missing \(key)")
        return try XCTUnwrap(Data(hex: str), "bad hex in \(key)")
    }

    private func str(_ s: [String: Any], _ key: String) throws -> String {
        return try XCTUnwrap(s[key] as? String)
    }

    private func priv(_ s: [String: Any], _ key: String) throws -> P256.KeyAgreement.PrivateKey {
        return try P256.KeyAgreement.PrivateKey(rawRepresentation: try hex(s, key))
    }

    func testHKDFRfc5869Case1() {
        let ikm = Data(repeating: 0x0b, count: 22)
        let salt = Data(hex: "000102030405060708090a0b0c")!
        let info = Data(hex: "f0f1f2f3f4f5f6f7f8f9")!
        let okm = BCrypto.hkdf(ikm: ikm, salt: salt, info: info, length: 42)
        XCTAssertEqual(
            okm.hex,
            "3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865")
    }

    func testPairServerSide() throws {
        let p = try section("pair")
        let r = try Handshake.serverPairRespond(
            hello: try hex(p, "hello_body"),
            deviceId: try hex(p, "server_device_id"),
            name: try str(p, "server_name"),
            ephemeral: try priv(p, "server_priv"),
            nonce: try hex(p, "server_nonce"))
        XCTAssertEqual(r.reply, try hex(p, "reply_body"))
        XCTAssertEqual(r.keys.c2s, try hex(p, "c2s_key"))
        XCTAssertEqual(r.keys.s2c, try hex(p, "s2c_key"))
        XCTAssertEqual(r.keys.secret, try hex(p, "pairing_secret"))
        XCTAssertEqual(r.keys.sas, try str(p, "sas"))
        XCTAssertEqual(r.clientId, try hex(p, "client_device_id"))
        XCTAssertEqual(r.clientName, try str(p, "client_name"))
    }

    func testReconnectServerSide() throws {
        let p = try section("reconnect")
        let secret = try hex(p, "pairing_secret")
        let r = try Handshake.serverReconnectRespond(
            hello: try hex(p, "hello_body"), secret: secret,
            ephemeral: try priv(p, "server_priv"), nonce: try hex(p, "server_nonce"))
        XCTAssertEqual(r.reply, try hex(p, "reply_body"))
        XCTAssertEqual(r.transcriptHash, try hex(p, "transcript_hash"))
        XCTAssertEqual(r.sharedSecret, try hex(p, "shared_secret"))
        let keys = try Handshake.serverReconnectFinish(
            finish: try hex(p, "finish_body"), secret: secret,
            transcriptHash: r.transcriptHash, sharedSecret: r.sharedSecret)
        XCTAssertEqual(keys.c2s, try hex(p, "c2s_key"))
        XCTAssertEqual(keys.s2c, try hex(p, "s2c_key"))
    }

    func testForgedClientMacIsRejected() throws {
        let p = try section("reconnect")
        let secret = try hex(p, "pairing_secret")
        let r = try Handshake.serverReconnectRespond(
            hello: try hex(p, "hello_body"), secret: secret,
            ephemeral: try priv(p, "server_priv"), nonce: try hex(p, "server_nonce"))
        var finish = try hex(p, "finish_body")
        finish[finish.count - 1] ^= 1
        XCTAssertThrowsError(try Handshake.serverReconnectFinish(
            finish: finish, secret: secret, transcriptHash: r.transcriptHash, sharedSecret: r.sharedSecret))
        XCTAssertThrowsError(try Handshake.serverReconnectFinish(
            finish: try hex(p, "finish_body"), secret: Data(repeating: 0, count: 32),
            transcriptHash: r.transcriptHash, sharedSecret: r.sharedSecret))
    }

    func testStateMachineReconnectAndPair() throws {
        let rc = try section("reconnect")
        let secret = try hex(rc, "pairing_secret")
        let clientId = try hex(rc, "client_device_id")
        let hs = ServerHandshake(
            deviceId: Data(repeating: 1, count: 16), name: "Mac",
            pairingEnabled: { false },
            lookupSecret: { $0 == clientId ? secret : nil },
            ephemeral: try priv(rc, "server_priv"), nonce: try hex(rc, "server_nonce"))
        guard case .reply(let reply) = try hs.receive(frame: try hex(rc, "hello_body")) else {
            return XCTFail("expected reply")
        }
        XCTAssertEqual(reply, try hex(rc, "reply_body"))
        guard case .established(let est, let extra) = try hs.receive(frame: try hex(rc, "finish_body")) else {
            return XCTFail("expected established")
        }
        XCTAssertNil(extra)
        XCTAssertEqual(est.peerId, clientId)
        XCTAssertEqual(est.mode, .reconnect)
        // The established codec talks to a client codec built from the same vector keys.
        let client = RecordCodec(sendKey: try hex(rc, "c2s_key"), recvKey: try hex(rc, "s2c_key"))
        let sealed = try client.seal(type: 1, body: Data("hi".utf8))
        let opened = try est.codec.open(sealed.sub(4, sealed.count))
        XCTAssertEqual(opened.type, 1)
        XCTAssertEqual(opened.body, Data("hi".utf8))

        // Unknown device
        let hs2 = ServerHandshake(
            deviceId: Data(repeating: 1, count: 16), name: "Mac",
            pairingEnabled: { false }, lookupSecret: { _ in nil })
        XCTAssertThrowsError(try hs2.receive(frame: try hex(rc, "hello_body")))

        // Pairing refused unless enabled
        let pr = try section("pair")
        let hs3 = ServerHandshake(
            deviceId: try hex(pr, "server_device_id"), name: try str(pr, "server_name"),
            pairingEnabled: { false }, lookupSecret: { _ in nil })
        XCTAssertThrowsError(try hs3.receive(frame: try hex(pr, "hello_body")))

        let hs4 = ServerHandshake(
            deviceId: try hex(pr, "server_device_id"), name: try str(pr, "server_name"),
            pairingEnabled: { true }, lookupSecret: { _ in nil },
            ephemeral: try priv(pr, "server_priv"), nonce: try hex(pr, "server_nonce"))
        guard case .established(let pest, let preply) = try hs4.receive(frame: try hex(pr, "hello_body")) else {
            return XCTFail("expected established")
        }
        XCTAssertEqual(preply, try hex(pr, "reply_body"))
        XCTAssertEqual(pest.sas, try str(pr, "sas"))
        XCTAssertEqual(pest.pairingSecret, try hex(pr, "pairing_secret"))
        XCTAssertEqual(pest.peerName, try str(pr, "client_name"))
    }

    func testRecords() throws {
        let r = try section("records")
        let key = try hex(r, "key")
        let items = try XCTUnwrap(r["items"] as? [[String: Any]])
        XCTAssertFalse(items.isEmpty)
        let sender = RecordCodec(sendKey: key, recvKey: key)
        let receiver = RecordCodec(sendKey: key, recvKey: key)
        for item in items {
            let type = UInt8(try XCTUnwrap(item["type"] as? Int))
            let body = try hex(item, "body")
            let frameBytes = try hex(item, "frame")
            XCTAssertEqual(try sender.seal(type: type, body: body), frameBytes)
            let opened = try receiver.open(frameBytes.sub(4, frameBytes.count))
            XCTAssertEqual(opened.type, type)
            XCTAssertEqual(opened.body, body)
        }
    }

    func testTamperAndReplayAreRejected() throws {
        let r = try section("records")
        let key = try hex(r, "key")
        let items = try XCTUnwrap(r["items"] as? [[String: Any]])
        let f0 = try hex(items[0], "frame")
        var bad = f0.sub(4, f0.count)
        bad[0] ^= 1
        XCTAssertThrowsError(try RecordCodec(sendKey: key, recvKey: key).open(bad))

        let rx = RecordCodec(sendKey: key, recvKey: key)
        _ = try rx.open(f0.sub(4, f0.count))
        XCTAssertThrowsError(try rx.open(f0.sub(4, f0.count)), "replayed record must fail")
    }

    func testPublicKeyValidation() throws {
        let k = P256.KeyAgreement.PrivateKey()
        XCTAssertThrowsError(try BCrypto.ecdh(k, peerPublic: Data(repeating: 4, count: 65)))
        XCTAssertThrowsError(try BCrypto.ecdh(k, peerPublic: Data(repeating: 0, count: 65)))
        XCTAssertThrowsError(try BCrypto.ecdh(k, peerPublic: Data(count: 10)))
    }

    func testFrameDecoder() throws {
        var d = FrameDecoder()
        let a = Data("abc".utf8), b = Data("defgh".utf8)
        let stream = frame(a) + frame(b)
        d.append(stream.sub(0, 5))
        XCTAssertNil(try d.next())
        d.append(stream.sub(5, stream.count))
        XCTAssertEqual(try d.next(), a)
        XCTAssertEqual(try d.next(), b)
        XCTAssertNil(try d.next())
        var bad = FrameDecoder()
        bad.append(Data([0, 0, 0, 0]))
        XCTAssertThrowsError(try bad.next())
        var huge = FrameDecoder()
        huge.append(Data.beBytes(UInt32(Wire.maxFrame + 1)))
        XCTAssertThrowsError(try huge.next())
    }

    func testNameClippingAndFileNames() {
        let long = String(repeating: "я", count: 100) // 200 bytes
        let clipped = Handshake.clipName(long)
        XCTAssertLessThanOrEqual(clipped.count, 64)
        XCTAssertNotNil(String(data: clipped, encoding: .utf8))
        XCTAssertEqual(clipped.count, 64)

        XCTAssertEqual(FileNames.safe("../../etc/passwd"), "passwd")
        XCTAssertEqual(FileNames.safe("C:\\dir\\a<b>.txt"), "a_b_.txt")
        XCTAssertEqual(FileNames.safe("  ..  "), "file")
        XCTAssertEqual(FileNames.safe(""), "file")
        XCTAssertEqual(FileNames.safe("a\u{01}b"), "a_b")
        XCTAssertEqual(FileNames.safe("фото.jpg"), "фото.jpg")
        XCTAssertEqual(FileNames.safe(String(repeating: "x", count: 300)).count, 200)
        XCTAssertEqual(FileNames.safe("dir/"), "file")
    }
}
